package com.mohymods.kingdomsmp.profession;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.network.*;
import com.mohymods.kingdomsmp.persistence.*;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.InteractionHand;
import java.io.IOException;
import java.util.*;
/** Resource-consuming contracts share the existing native receipt and canonical money authority. */
public final class ContractService {
 public record Quote(UUID nonce,long revision,ContractRules.Terms terms,long period,long issued,List<ItemStack> inventory,String text){public Quote{inventory=inventory.stream().map(ItemStack::copy).toList();}}
 private static final Map<ServerPlayer,Quote> QUOTES=new WeakHashMap<>();
 private ContractService(){ }
 public static void initialize(MinecraftServer server){com.mohymods.kingdomsmp.bounty.CommunityContractService.initialize(server);com.mohymods.kingdomsmp.bounty.HuntService.initialize(server);ContractRules.clear(server);QUOTES.keySet().removeIf(p->p.server==server);}
 public static void close(ServerPlayer p){QUOTES.remove(p);com.mohymods.kingdomsmp.bounty.CommunityContractService.close(p);com.mohymods.kingdomsmp.bounty.HuntService.close(p);}
 public static Optional<Quote> quote(ServerPlayer p){var q=QUOTES.get(p);if(q!=null&&(q.revision()!=CommerceService.store(p.server).revision()||System.nanoTime()-q.issued()>30_000_000_000L||q.period()!=ContractRules.period(q.terms().cycle()))){close(p);q=null;}return Optional.ofNullable(q);}
 static void requireCounter(ServerPlayer p,Profession role){
  CommerceService.requireResidentCounter(p);if(!CommerceService.store(p.server).professions(p.getUUID()).isActive(role))throw new IllegalStateException("Activate the matching profession before delivering its contract.");
  boolean nearby=ConstructionService.store(p.server).projects().stream().filter(v->v.phase()==ConstructionStore.Phase.COMPLETE&&!v.npcDead()&&v.blueprint().toString().equals(role.buildingId())&&ConstructionService.structureIntact(p.serverLevel(),v)).anyMatch(v->{var npc=p.serverLevel().getEntity(v.npc());return npc instanceof com.mohymods.kingdomsmp.npc.ReeveEntity resident&&ConstructionService.registeredReeve(resident)&&p.distanceToSqr(npc)<=64&&p.hasLineOfSight(npc)&&com.mohymods.kingdomsmp.placement.PlacementProtection.entityInteraction(p,npc)==null;});
  if(!nearby)throw new IllegalStateException("Visit the assigned "+ProfessionService.name(role)+" resident within eight blocks and clear sight.");
 }
 private static int count(ServerPlayer p,ItemStack item){int sum=0;for(int i=0;i<36;i++){var stack=p.getInventory().getItem(i);if(ItemStack.isSameItemSameComponents(stack,item))sum+=stack.getCount();}return sum;}
 private static void validateSpread(ServerPlayer p,ContractRules.Terms terms){var market=MarketService.catalog(p.server);for(var supply:CommerceService.catalog(p.server).supplies())if(supply.item()==terms.item()&&terms.reward()>=Math.multiplyExact(market.rule(supply.id()).minimumSell(),terms.quantity()))throw new IllegalStateException("Contract reward would allow a profitable NPC stock loop; configure a strictly lower reward.");}
 public static Quote review(ServerPlayer p,String id)throws IOException{com.mohymods.kingdomsmp.bounty.CommunityContractService.close(p);com.mohymods.kingdomsmp.bounty.HuntService.close(p);var terms=ContractRules.get(p.server).get(id);requireCounter(p,terms.profession());validateSpread(p,terms);var s=CommerceService.store(p.server);CommerceService.verifyReceipt(p,s);long period=ContractRules.period(terms.cycle());if(s.contractCompleted(p.getUUID(),terms.profession().id(),terms.cycle(),period))throw new IllegalStateException("This profession contract was already completed in the current period.");if(terms.reward()>terms.pool()-s.contractPoolSpent(terms.cycle(),period))throw new IllegalStateException("The shared contract reward pool is exhausted for this period.");if(count(p,new ItemStack(terms.item()))<terms.quantity())throw new IllegalStateException("Bring "+terms.quantity()+" plain "+terms.item().getDescription().getString()+" for the full delivery. Nothing has been consumed.");List<ItemStack> inventory=new ArrayList<>();for(int i=0;i<36;i++)inventory.add(p.getInventory().getItem(i).copy());String text="Permanently deliver exactly "+terms.quantity()+" plain "+terms.item().getDescription().getString()+" for "+terms.reward()+" coins in private coin mail. One "+terms.cycle()+" contract per active profession/period. Shared pool "+s.contractPoolSpent(terms.cycle(),period)+" / "+terms.pool()+". Claim payment from your Mailbox. Contracts count towards eligible profession objectives only when completed during that objective band; they grant no automatic XP.";var q=new Quote(UUID.randomUUID(),s.revision(),terms,period,System.nanoTime(),inventory,text);QUOTES.put(p,q);return q;}
 public static String confirm(ServerPlayer p,UUID nonce)throws IOException{
  var q=QUOTES.remove(p);var s=CommerceService.store(p.server);CommerceService.verifyReceipt(p,s);if(q==null||!q.nonce().equals(nonce)||q.revision()!=s.revision()||q.period()!=ContractRules.period(q.terms().cycle())||System.nanoTime()-q.issued()>30_000_000_000L)throw new IllegalStateException("Contract review expired, period changed or reward state changed. Review again.");requireCounter(p,q.terms().profession());validateSpread(p,q.terms());for(int i=0;i<36;i++)if(!ItemStack.matches(p.getInventory().getItem(i),q.inventory().get(i)))throw new IllegalStateException("Inventory changed; review the exact contract again.");
  var old=p.getPersistentData().copy();boolean checkpointStarted=false;try{
   CommerceService.checkpoint(p);var item=new ItemStack(q.terms().item());var pending=s.prepareContract(q.nonce(),p.getUUID(),q.terms().profession().id(),q.terms().cycle(),q.period(),q.terms().quantity(),q.terms().reward(),q.terms().pool(),(CompoundTag)item.save(p.registryAccess()));int remaining=q.terms().quantity();for(int i=0;i<36&&remaining>0;i++){var stack=p.getInventory().getItem(i);if(ItemStack.isSameItemSameComponents(stack,item)){int n=Math.min(remaining,stack.getCount());stack.shrink(n);remaining-=n;}}if(remaining!=0)throw new IllegalStateException("Contract inventory changed during commit");CommerceService.putReceipt(p,new EconomyStore.Receipt(s.id(),pending.sequence()));checkpointStarted=true;CommerceService.checkpoint(p);if(!s.recoverItem(CommerceService.receipt(AtomicNbt.read(CommerceService.playerFile(p.server,p.getUUID())))))throw new IOException("Contract native receipt not committed");p.getInventory().setChanged();p.inventoryMenu.sendAllDataToRemote();return "Delivery saved once. Claim "+q.terms().reward()+" coins from your private Mailbox; the shared pool and completion record are persistent.";
  }catch(IOException|RuntimeException e){if(!checkpointStarted){for(int i=0;i<36;i++)p.getInventory().setItem(i,q.inventory().get(i).copy());for(var key:new HashSet<>(p.getPersistentData().getAllKeys()))p.getPersistentData().remove(key);p.getPersistentData().merge(old);}if(!checkpointStarted&&s.pendingItem().isEmpty()&&!s.quarantined()&&(e instanceof IllegalArgumentException||e instanceof IllegalStateException))throw e;s.quarantine();p.connection.disconnect(net.minecraft.network.chat.Component.literal("Contract inventory interrupted; matching checkpoint recovery is required."));throw e;}
 }
 public static List<CommerceView.Entry> entries(ServerPlayer p){var s=CommerceService.store(p.server);List<CommerceView.Entry> rows=new ArrayList<>();for(var terms:ContractRules.get(p.server).all()){long period=ContractRules.period(terms.cycle());boolean complete=s.contractCompleted(p.getUUID(),terms.profession().id(),terms.cycle(),period),active=s.professions(p.getUUID()).isActive(terms.profession());rows.add(new CommerceView.Entry(ContractRules.id(terms),ProfessionService.name(terms.profession())+" · "+terms.cycle(),"Deliver "+terms.quantity()+" plain "+terms.item().getDescription().getString()+" at its profession resident. Shared reward pool "+s.contractPoolSpent(terms.cycle(),period)+"/"+terms.pool()+". "+(terms.cycle().equals("daily")?"Resets daily at 00:00 UTC. ":"Resets Monday at 00:00 UTC. ")+(complete?"Already completed.":!active?"Matching profession must be active.":"Review actual inventory before delivery."),terms.reward(),complete?"CONTRACT_DONE":active?"CONTRACT":"LOCKED"));}return List.copyOf(rows);}
}
